// §19 WF10 — คัดกรองการแจ้งเตือน: กันซ้ำ + ช่วงเวลางดรบกวน + จัดลำดับความสำคัญ
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const s = (v, m) => (v === null || v === undefined) ? '' : String(v).trim().slice(0, m);
const TYPE_MAP = {
  lead_new: { level: 'normal', label: 'ผู้สนใจใหม่' }, lead_hot: { level: 'urgent', label: 'ผู้สนใจคะแนนสูง' },
  followup_due: { level: 'high', label: 'ถึงกำหนดติดตาม' }, appointment: { level: 'high', label: 'นัดหมาย' },
  income: { level: 'normal', label: 'รายได้/ค่าตอบแทน' }, member_new: { level: 'normal', label: 'สมาชิกใหม่' },
  system: { level: 'low', label: 'ระบบ' }, error: { level: 'urgent', label: 'ข้อผิดพลาดระบบ' },
};
const key = s(body.event || body.type || 'system', 40).toLowerCase();
const meta = TYPE_MAP[key] || { level: s(body.level, 20) || 'normal', label: key };
const dedupeKey = s(body.dedupeKey || body.idempotencyKey, 160) || (key + ':' + s(body.subject || body.detail, 80));
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
sd.queue = Array.isArray(sd.queue) ? sd.queue : [];
const now = Date.now();
if (sd.seen[dedupeKey] && now - sd.seen[dedupeKey] < 6 * 3600e3) {
  return [{ json: { ok: true, sent: false, reason: 'duplicate', dedupeKey, level: meta.level, label: meta.label } }];
}
sd.seen[dedupeKey] = now;
const keys = Object.keys(sd.seen);
if (keys.length > 400) for (const k of keys.sort((a, b) => sd.seen[a] - sd.seen[b]).slice(0, 200)) delete sd.seen[k];
const hourBkk = Number(new Date().toLocaleString('en-GB', { timeZone: 'Asia/Bangkok', hour: '2-digit', hour12: false }));
const quiet = hourBkk >= 22 || hourBkk < 7;
const urgent = meta.level === 'urgent';
const shouldSend = urgent || !quiet;
const item = { dedupeKey, event: key, label: meta.label, level: meta.level, quiet, urgent,
  title: s(body.subject || body.title, 160) || meta.label, detail: s(body.detail || body.message, 900),
  prospectId: body.prospectId || null, agent: s(body.agent, 80) || null, at: new Date().toISOString() };
if (!shouldSend) {
  sd.queue.push(item);
  if (sd.queue.length > 100) sd.queue = sd.queue.slice(-100);
  return [{ json: Object.assign({}, item, { ok: true, sent: false, reason: 'quiet_hours_queued', queueSize: sd.queue.length, shouldSend: false }) }];
}
return [{ json: Object.assign({}, item, { ok: true, sent: true, shouldSend: true }) }];

// ปล่อยคิวที่ค้างช่วงเวลางดรบกวน
const sd = $getWorkflowStaticData('global');
sd.queue = Array.isArray(sd.queue) ? sd.queue : [];
const hourBkk = Number(new Date().toLocaleString('en-GB', { timeZone: 'Asia/Bangkok', hour: '2-digit', hour12: false }));
const canFlush = !(hourBkk >= 22 || hourBkk < 7);
const out = canFlush ? sd.queue : [];
if (canFlush) sd.queue = [];
return [{ json: { canFlush, flushed: out.length, pending: sd.queue.length, items: out,
  digest: out.map(i => '• [' + i.level + '] ' + i.label + ' — ' + i.title + (i.detail ? (' · ' + i.detail) : '')).join('\n') } }];

const log = $json || {};
const f = $('ปล่อยคิวหลังเวลาเงียบ').first().json;
return [{ json: { ok: true, flushed: f.flushed, emailed: log.email || 'skipped', pending: f.pending } }];
